SELECT s.s_store_id, d.d_date, SUM(ss.ss_net_paid) AS total_sales, COUNT(*) AS total_transactions, (SELECT d2.d_day_name FROM date_dim d2 WHERE d2.d_date_sk = d.d_date_sk) AS day_name FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN store_returns sr ON sr.sr_ticket_number = ss.ss_ticket_number WHERE d.d_year = 1913 AND s.s_state = 'CO' GROUP BY s.s_store_id, d.d_date, d.d_date_sk HAVING SUM(ss.ss_net_paid) > 2539.84
